import boto3
from typing import Dict, List, Any

def extract_invoice_fields(invoice_bytes: bytes) -> Dict[str, Any]:
    client = boto3.client('textract')
    response = client.analyze_expense(
        Document={'Bytes': invoice_bytes}
    )
    if 'ExpenseDocuments' not in response or not response['ExpenseDocuments']:
        return {'vendor': '', 'date': '', 'total': '', 'line_items': []}
    doc = response['ExpenseDocuments'][0]

    # Extract summary fields
    summary_fields: Dict[str, str] = {}
    for field in doc.get('SummaryFields', []):
        field_type = field['Type']['Text']
        value = field['ValueDetection']['Text']
        summary_fields[field_type] = value

    vendor = summary_fields.get('VENDOR_NAME', '')
    date = summary_fields.get('INVOICE_DATE', '')
    total = summary_fields.get('INVOICE_TOTAL', '')

    # Extract line items
    line_items: List[Dict[str, str]] = []
    for group in doc.get('LineItemGroups', []):
        for item in group.get('LineItems', []):
            item_data: Dict[str, str] = {'description': item.get('Text', '')}
            for prop in item.get('ItemExpenseProperties', []):
                prop_type = prop['Type']['Text'].lower().replace(' ', '_')
                prop_value = prop['ValueDetection']['Text']
                item_data[prop_type] = prop_value
            line_items.append(item_data)

    return {
        'vendor': vendor,
        'date': date,
        'total': total,
        'line_items': line_items
    }
